const { useState } = React;
const root = ReactDOM.createRoot(document.querySelector('#root'));

const Card = () => {
  const [option, setOption] = useState({ color: '흰색', size: 'M' });

  console.log('그려집니다. 색 =', option.color, '/ 사이즈 =', option.size);

  const pickBlack = () => setOption({ ...option, color: '검정' });
  const pickLarge = () => setOption({ ...option, size: 'L' });

  return (
    <article className="card">
      <h3 className="card__title">오버사이즈 셔츠</h3>
      <p className="card__option">{option.color} · {option.size}</p>
      <div className="row">
        <button className="color-black" type="button" onClick={pickBlack}>검정</button>
        <button className="large" type="button" onClick={pickLarge}>L</button>
      </div>
    </article>
  );
};

root.render(<Card />);

