const { useState } = React;
const root = ReactDOM.createRoot(document.querySelector('#root'));

const Card = () => {
  const [option, setOption] = useState({ color: '흰색', size: 'M' });

  return (
    <article className="card">
      <h3 className="card__title">오버사이즈 셔츠</h3>
      <p className="card__option">{option.color} · {option.size}</p>
      <div className="row">
        <button className="color-white" type="button" onClick={() => setOption({ ...option, color: '흰색' })}>흰색</button>
        <button className="color-black" type="button" onClick={() => setOption({ ...option, color: '검정' })}>검정</button>
        <button className="size-m" type="button" onClick={() => setOption({ ...option, size: 'M' })}>M</button>
        <button className="size-l" type="button" onClick={() => setOption({ ...option, size: 'L' })}>L</button>
      </div>
    </article>
  );
};

root.render(<Card />);
